// Requires: mesh OBJ (File → Open Mesh OBJ)
// Vertex layout: position (float3), normal (float3), UV (float2)

struct VSInput
{
    float3 pos    : POSITION;
    float3 normal : NORMAL;
    float2 uv     : TEXCOORD0;
};

struct VSOutput
{
    float3 worldPos : WORLDPOS;
    float3 normal   : NORMAL;
    float2 uv       : TEXCOORD0;
};

VSOutput VSMain(VSInput input)
{
    VSOutput o;
    o.worldPos = input.pos;
    o.normal = normalize(input.normal);
    o.uv = input.uv;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOutput
{
    float3 worldPos : WORLDPOS;
    float3 normal   : NORMAL;
    float2 uv       : TEXCOORD0;
};

struct HSOutput
{
    float3 worldPos : WORLDPOS;
    float3 normal   : NORMAL;
    float2 uv       : TEXCOORD0;
};

struct HSConstOutput
{
    float edges[3]  : SV_TessFactor;
    float inside    : SV_InsideTessFactor;
};

float computeTessFactor(float3 patchCenter)
{
    float angle = drag_accum_x * 0.01;
    float elevation = clamp(-drag_accum_y * 0.01, -1.4, 1.4);
    float dist = max(0.5, 3.0 - scroll_accum_y * 0.3);
    float3 fwd = float3(sin(angle)*cos(elevation), sin(elevation), cos(angle)*cos(elevation));
    float3 right = normalize(cross(float3(0,1,0), fwd));
    float3 camUp = cross(fwd, right);
    float panScale = dist * 0.002;
    float3 panOff = right * (-pan_accum_x * panScale) + camUp * (pan_accum_y * panScale);
    float3 eye = panOff + float3(cos(angle)*cos(elevation)*dist, sin(elevation)*dist, sin(angle)*cos(elevation)*dist);
    float d = length(patchCenter - eye);
    float maxTess = 12.0;
    float minTess = 1.0;
    float nearDist = 1.0;
    float farDist = 5.0;
    float t = saturate((d - nearDist) / (farDist - nearDist));
    return lerp(maxTess, minTess, t);
}

HSConstOutput PatchConstFunc(InputPatch<VSOutput, 3> patch, uint patchID : SV_PrimitiveID)
{
    HSConstOutput o;
    float3 center = (patch[0].worldPos + patch[1].worldPos + patch[2].worldPos) / 3.0;
    float tess = computeTessFactor(center);
    o.edges[0] = tess;
    o.edges[1] = tess;
    o.edges[2] = tess;
    o.inside = tess;
    return o;
}

[domain("tri")]
[partitioning("fractional_even")]
[outputtopology("triangle_cw")]
[outputcontrolpoints(3)]
[patchconstantfunc("PatchConstFunc")]
HSOutput HSMain(InputPatch<VSOutput, 3> patch, uint cpID : SV_OutputControlPointID)
{
    HSOutput o;
    o.worldPos = patch[cpID].worldPos;
    o.normal = patch[cpID].normal;
    o.uv = patch[cpID].uv;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct HSOutput
{
    float3 worldPos : WORLDPOS;
    float3 normal   : NORMAL;
    float2 uv       : TEXCOORD0;
};

struct HSConstOutput
{
    float edges[3]  : SV_TessFactor;
    float inside    : SV_InsideTessFactor;
};

struct DSOutput
{
    float4 pos    : SV_POSITION;
    float3 normal : NORMAL;
    float2 uv     : TEXCOORD0;
    float  tess   : TESS_LEVEL;
};

float4x4 lookAtRH(float3 eye, float3 target, float3 up)
{
    float3 f = normalize(target - eye);
    float3 r = normalize(cross(f, up));
    float3 u = cross(r, f);
    return float4x4(
        r.x, u.x, -f.x, 0,
        r.y, u.y, -f.y, 0,
        r.z, u.z, -f.z, 0,
        -dot(r,eye), -dot(u,eye), dot(f,eye), 1);
}

float4x4 perspectiveRH(float fovY, float aspect, float zn, float zf)
{
    float h = 1.0 / tan(fovY * 0.5);
    float w = h / aspect;
    float a = zf / (zn - zf);
    float b = zn * a;
    return float4x4(
        w, 0, 0, 0,
        0, h, 0, 0,
        0, 0, a, -1,
        0, 0, b, 0);
}

[domain("tri")]
DSOutput DSMain(HSConstOutput patchConst, float3 bary : SV_DomainLocation,
                const OutputPatch<HSOutput, 3> patch)
{
    DSOutput o;
    float3 worldPos = bary.x * patch[0].worldPos + bary.y * patch[1].worldPos + bary.z * patch[2].worldPos;
    float3 normal = normalize(bary.x * patch[0].normal + bary.y * patch[1].normal + bary.z * patch[2].normal);
    float2 uv = bary.x * patch[0].uv + bary.y * patch[1].uv + bary.z * patch[2].uv;

    float aspect = resolution_x / resolution_y;
    float angle = drag_accum_x * 0.01;
    float elevation = clamp(-drag_accum_y * 0.01, -1.4, 1.4);
    float dist = max(0.5, 3.0 - scroll_accum_y * 0.3);
    float3 fwd = float3(sin(angle)*cos(elevation), sin(elevation), cos(angle)*cos(elevation));
    float3 right = normalize(cross(float3(0,1,0), fwd));
    float3 camUp = cross(fwd, right);
    float panScale = dist * 0.002;
    float3 panOff = right * (-pan_accum_x * panScale) + camUp * (pan_accum_y * panScale);
    float3 eye = panOff + float3(cos(angle)*cos(elevation)*dist, sin(elevation)*dist, sin(angle)*cos(elevation)*dist);
    float4x4 view = lookAtRH(eye, panOff, float3(0,1,0));
    float4x4 proj = perspectiveRH(1.0, aspect, 0.1, 100.0);

    o.pos = mul(proj, mul(view, float4(worldPos, 1.0)));
    o.normal = normal;
    o.uv = uv;
    o.tess = patchConst.inside;
    return o;
}

struct DSOutput
{
    float4 pos    : SV_POSITION;
    float3 normal : NORMAL;
    float2 uv     : TEXCOORD0;
    float  tess   : TESS_LEVEL;
};

float4 PSMain(DSOutput input) : SV_Target
{
    float3 n = normalize(input.normal);
    float3 lightDir = normalize(float3(0.5, 1.0, 0.3));
    float diff = saturate(dot(n, lightDir));
    float t = saturate(input.tess / 12.0);
    float3 lowColor = float3(0.2, 0.4, 0.8);
    float3 highColor = float3(0.9, 0.3, 0.1);
    float3 baseColor = lerp(lowColor, highColor, t);
    float3 color = baseColor * (diff * 0.7 + 0.3);
    return float4(color, 1.0);
}
